fn calc_ns_per_timer_tick(
    nominal: NominalBitTiming,
    freq: crate::time::Hertz,
    mode: crate::can::fd::config::FrameTransmissionConfig,
    timestamp_source: TimestampSource,
) -> u64 {
    match (timestamp_source, mode) {
        (TimestampSource::None, _) | (TimestampSource::FromTIM3, _) => 0,
        (TimestampSource::Prescaler(tcp), FrameTransmissionConfig::ClassicCanOnly) => {
            // TSCC.TCP counts whole CAN bit times, including the sync segment.
            // Use the requested config: start() has not programmed NBTP/TSCC yet.
            let quanta_per_bit = 1 + u64::from(nominal.seg1.get()) + u64::from(nominal.seg2.get());
            let cycles_per_tick = u64::from(nominal.prescaler.get()) * quanta_per_bit * tcp as u64;
            1_000_000_000_u64 * cycles_per_tick / u64::from(freq.0)
        }
        // The internal counter has no constant period when CAN FD switches rates.
        _ => 0,
    }
}
